import os
import subprocess
import yaml

def find_modified_deliverable_files(reportoot):
    results = subprocess.check_output(
        ['git', 'diff', '--name-only', '--diff-filter=AM', '--no-ext-diff'],
        cwd=reportoot,
    )
    filenames = [
        l.strip()
        for l in results.splitlines()
        if l.startswith('src/deliverables/')
    ]
    return filenames

def get_modified_deliverable_file_content(reportoot, filenames):
    """Get the content of modified deliverable files."""
    deliverable_files = filenames
    if not deliverable_files:
        deliverable_files = find_modified_deliverable_files(reportoot)
    for basename in deliverable_files:
        deliverable_path = os.path.join(reportoot, basename)
        with open(deliverable_path, 'r') as f:
            content = f.read()
        yield content

